package dev.differentenchant;

import java.util.*;
import java.nio.file.*;
import dev.differentenchant.workstation.*;
import dev.differentenchant.disenchant.*;
import dev.differentenchant.research.*;
import dev.differentenchant.client.*;
import net.fabricmc.fabric.api.client.gametest.v1.FabricClientGameTest;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.fabricmc.fabric.api.client.gametest.v1.world.TestWorldSave;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;

/** Real native client controls, actual particles, block mining, menus and on-disk reopening. */
public final class WorkstationClientGameTest implements FabricClientGameTest {
    private static final BlockPos D=new BlockPos(0,-59,0),R=new BlockPos(7,-59,0);
    private static void check(boolean v,String message){DisenchantGameTests.check(v,message);}
    private static void language(ClientGameTestContext c,String code){var f=c.computeOnClient(client->{client.getLanguageManager().setSelected(code);client.options.languageCode=code;return client.reloadResourcePacks();});c.waitFor(client->f.isDone()&&client.getOverlay()==null);c.waitTicks(4);}
    private static void aim(ClientGameTestContext c,double x,double y,double z){var a=c.computeOnClient(client->{var e=client.player.getEyePosition();double dx=x-e.x,dy=y-e.y,dz=z-e.z;return new float[]{(float)(Math.toDegrees(Math.atan2(dz,dx))-90),(float)-Math.toDegrees(Math.atan2(dy,Math.sqrt(dx*dx+dz*dz)))};});c.getInput().lookAt(a[0],a[1]);}
    private static void shot(ClientGameTestContext c,String name){c.runOnClient(client->{client.getToastManager().clear();client.gui.getChat().clearMessages(true);});c.getInput().setCursorPos(1,1);c.waitTicks(8);c.takeScreenshot("workstation-"+name);}
    private static void cursor(ClientGameTestContext c,int x,int y,boolean research){int height=research?ResearchMenu.HEIGHT:DisenchantMenu.HEIGHT;var a=c.computeOnClient(client->{double scale=client.getWindow().getGuiScale();return new double[]{((client.screen.width-230)/2+x)*scale,((client.screen.height-height)/2+y)*scale};});c.getInput().setCursorPos(a[0],a[1]);c.waitTick();}
    private static void click(ClientGameTestContext c,int x,int y,boolean research){cursor(c,x,y,research);c.getInput().pressMouse(0);c.waitTicks(4);}
    private static void shift(ClientGameTestContext c,int x,int y,boolean research){cursor(c,x,y,research);int height=research?ResearchMenu.HEIGHT:DisenchantMenu.HEIGHT;c.runOnClient(client->{var e=new net.minecraft.client.input.MouseButtonEvent((client.screen.width-230)/2+x,(client.screen.height-height)/2+y,new net.minecraft.client.input.MouseButtonInfo(0,1));client.screen.mouseClicked(e,false);client.screen.mouseReleased(e);});c.waitTicks(4);}
    private static void close(ClientGameTestContext c){c.getInput().pressKey(o->o.keyInventory);c.waitForScreen(null);c.waitTicks(3);}
    private static void form(ClientGameTestContext c,BlockPos core){c.getInput().pressKey(o->o.keyHotbarSlots[7]);c.waitTicks(3);c.getInput().holdKey(o->o.keyShift);c.waitTicks(4);aim(c,core.getX()+.5,core.getY()+.84,core.getZ()+.5);c.waitTicks(3);c.runOnClient(client->check(client.player.getMainHandItem().isEmpty()&&client.hitResult instanceof net.minecraft.world.phys.BlockHitResult hit&&hit.getBlockPos().equals(core),"actual client empty hand aims at controller: "+client.player.getMainHandItem()+" / "+client.hitResult));c.getInput().pressKey(o->o.keyUse);c.waitTicks(4);c.getInput().releaseKey(o->o.keyShift);}
    private static void open(ClientGameTestContext c,BlockPos core,boolean research){aim(c,core.getX()+.5,core.getY()+.5,core.getZ()+.5);c.waitTicks(3);c.getInput().pressKey(o->o.keyUse);if(research)c.waitForScreen(ResearchScreen.class);else c.waitForScreen(DisenchantScreen.class);c.waitTicks(4);}
    private static Map<String,Integer> counts(TestSingleplayerContext w){return w.getServer().computeOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var all=new ArrayList<ItemStack>();for(int i=0;i<p.getInventory().getContainerSize();i++)all.add(p.getInventory().getItem(i));if(p.containerMenu instanceof ResearchMenu m)for(int i=0;i<3;i++)all.add(m.getSlot(i).getItem());if(p.containerMenu instanceof DisenchantMenu m)for(int i=0;i<2;i++)all.add(m.getSlot(i).getItem());all.add(p.containerMenu.getCarried());for(var e:s.overworld().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(Vec3.atCenterOf(D),Vec3.atCenterOf(R)).inflate(20)))all.add(e.getItem());var result=new TreeMap<String,Integer>();for(var item:all)if(!item.isEmpty())result.merge(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item.getItem()).toString(),item.getCount(),Integer::sum);return result;});}
    private static Vec3 particlePosition(net.minecraft.client.particle.Particle p){var matcher=java.util.regex.Pattern.compile("Pos [(]([^,]+),([^,]+),([^)]+)[)]").matcher(p.toString());check(matcher.find(),"native particle exposes actual position for telemetry");return new Vec3(Double.parseDouble(matcher.group(1)),Double.parseDouble(matcher.group(2)),Double.parseDouble(matcher.group(3)));}
    @Override public void runTest(ClientGameTestContext c) {
        c.getInput().resizeWindow(1280,720);language(c,"en_us");TestWorldSave save;Map<String,Integer> savedItems;String researchData;UUID dId,rId;var report=new StringBuilder();var telemetry=new StringBuilder("sample,corner,x,y,z\n");ResearchPolicy.Recipe success;
        try(var w=c.worldBuilder().create()) {
            save=w.getWorldSave();w.getServer().runCommand("time set day");w.getServer().runCommand("weather clear");w.getServer().runCommand("difficulty peaceful");
            w.getServer().runOnServer(s->{var l=s.overworld();WorkstationFixtures.build(l,D,WorkstationStructure.Kind.DISENCHANT);WorkstationFixtures.build(l,R,WorkstationStructure.Kind.RESEARCH);for(int y=-60;y<=-58;y++)l.setBlockAndUpdate(new BlockPos(10,y,-3),Blocks.QUARTZ_BLOCK.defaultBlockState());var p=s.getPlayerList().getPlayers().getFirst();p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();p.giveExperienceLevels(40);p.teleportTo(3.5,-60,-4.5);});c.waitTicks(5);aim(c,.5,-58.8,.5);shot(c,"01-disenchanter-before-assembly");
            w.getServer().runOnServer(s->s.getPlayerList().getPlayers().getFirst().teleportTo(.5,-58,-.5));c.waitTicks(4);form(c,D);
            w.getServer().computeOnServer(s->{var master=WorkstationStructure.controller(s.overworld(),D,WorkstationStructure.Kind.DISENCHANT);check(master!=null,"native sneak-use assembled new disenchanter");s.overworld().setBlockAndUpdate(new BlockPos(2,-60,-3),Blocks.QUARTZ_BLOCK.defaultBlockState());s.getPlayerList().getPlayers().getFirst().teleportTo(2.5,-59,-2.5);return master.machineId();});c.waitTicks(5);aim(c,.5,-58.6,.5);shot(c,"02-disenchanter-assembled");
            c.waitFor(client->ConvergingMagic.snapshot(D).size()>=4);var mote=c.computeOnClient(client->{var list=ConvergingMagic.snapshot(D);check(list.stream().map(ConvergingMagic.Mote::corner).collect(java.util.stream.Collectors.toSet()).equals(Set.of(9,11,15,17)),"all four actual corners emit native particles");return list.getLast();});var a=c.computeOnClient(client->particlePosition(mote.particle()));shot(c,"03-purple-convergence-a");c.waitTicks(5);var b=c.computeOnClient(client->particlePosition(mote.particle()));check(b.subtract(Vec3.atCenterOf(D)).horizontalDistanceSqr()<a.subtract(Vec3.atCenterOf(D)).horizontalDistanceSqr(),"actual native particle moves horizontally toward controller");shot(c,"04-purple-convergence-b");
            for(int sample=0;sample<3;sample++){int label=sample;var lines=c.computeOnClient(client->{var out=new StringBuilder();for(var m:ConvergingMagic.snapshot(D)){var p=particlePosition(m.particle());out.append(label).append(',').append(m.corner()).append(',').append(p.x).append(',').append(p.y).append(',').append(p.z).append('\n');}return out.toString();});telemetry.append(lines);c.waitTicks(4);}
            open(c,D,false);c.runOnClient(client->check(ConvergingMagic.snapshot(D).isEmpty(),"particles do not overlap container GUI"));w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(DisenchantMenu)p.containerMenu;DisenchantGameTests.fill(m,DisenchantGameTests.fixture(s.overworld()),2);});c.waitTicks(4);click(c,70,84,false);c.waitFor(client->((DisenchantMenu)client.player.containerMenu).cost()==6&&client.player.containerMenu.getSlot(2).hasItem());shot(c,"05-disenchanting-gui");shift(c,194,42,false);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(DisenchantMenu)p.containerMenu;check(p.experienceLevel==34&&m.getSlot(1).getItem().getCount()==1&&DisenchantGameTests.rank(m.getSlot(0).getItem(),"minecraft:sharpness")==0&&DisenchantGameTests.rank(m.getSlot(0).getItem(),"minecraft:vanishing_curse")==1,"real shift extraction and curse unchanged");});shot(c,"06-disenchanting-committed");close(c);
            var edge=WorkstationStructure.position(D,10);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.getInventory().getItem(2).isEmpty(),"test pickaxe uses a free slot, preserves returned equipment");p.getInventory().setItem(2,new ItemStack(Items.DIAMOND_PICKAXE));});c.getInput().pressKey(o->o.keyHotbarSlots[2]);c.waitTicks(4);aim(c,edge.getX()+.25,edge.getY()+.25,edge.getZ()+.5);c.waitTicks(3);c.runOnClient(client->check(client.hitResult instanceof net.minecraft.world.phys.BlockHitResult hit&&hit.getBlockPos().equals(edge),"mining aims at the low formed conduit, not empty air above it"));c.getInput().holdKey(o->o.keyAttack);c.waitFor(client->!client.level.getBlockState(edge).is(DisenchantContent.PART));c.getInput().releaseKey(o->o.keyAttack);c.waitTicks(3);c.runOnClient(client->check(ConvergingMagic.snapshot(D).isEmpty(),"break instantly clears live motes"));w.getServer().runOnServer(s->{for(int i:new int[]{9,11,15,17}){var p=WorkstationStructure.position(D,i);var state=s.overworld().getBlockState(p);check(state.is(Blocks.AMETHYST_CLUSTER)&&state.getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.FACING)==net.minecraft.core.Direction.UP&&state.canSurvive(s.overworld(),p),"four native supported upward clusters restored");}check(WorkstationGameTests.items(s.overworld(),D,Items.AMETHYST_SHARD)==0,"actual mining of edge does not drop cluster shards");});aim(c,.5,-58.7,.5);shot(c,"07-disenchanter-restored-clusters");
            w.getServer().runOnServer(s->{s.overworld().setBlockAndUpdate(edge,Blocks.REDSTONE_BLOCK.defaultBlockState());var p=s.getPlayerList().getPlayers().getFirst();check(p.getInventory().getItem(3).isEmpty(),"empty hands for native reassembly");p.teleportTo(.5,-58,-.5);});c.waitTicks(3);form(c,D);w.getServer().runOnServer(s->{check(WorkstationStructure.controller(s.overworld(),D,WorkstationStructure.Kind.DISENCHANT)!=null,"native reassembly after restoring broken edge");s.getPlayerList().getPlayers().getFirst().teleportTo(10.5,-57,-2.5);});c.waitTicks(5);aim(c,7.5,-58.9,.5);shot(c,"08-research-frame-inward-lecterns");
            w.getServer().runOnServer(s->{s.getPlayerList().getPlayers().getFirst().teleportTo(6.5,-58,-.5);var pos=WorkstationStructure.position(R,10);s.overworld().setBlockAndUpdate(pos,s.overworld().getBlockState(pos).setValue(LecternBlock.FACING,net.minecraft.core.Direction.NORTH));});c.waitTicks(4);aim(c,7.5,-58.2,.5);c.getInput().pressKey(o->o.keyUse);c.waitTicks(3);c.runOnClient(client->check(client.screen==null,"unassembled controller does not open research GUI"));form(c,R);w.getServer().runOnServer(s->{check(WorkstationStructure.controller(s.overworld(),R,WorkstationStructure.Kind.RESEARCH)==null,"actual outward lectern prevents assembly");var pos=WorkstationStructure.position(R,10);s.overworld().setBlockAndUpdate(pos,s.overworld().getBlockState(pos).setValue(LecternBlock.FACING,net.minecraft.core.Direction.SOUTH));});c.waitTicks(3);form(c,R);
            rId=w.getServer().computeOnServer(s->{var master=WorkstationStructure.controller(s.overworld(),R,WorkstationStructure.Kind.RESEARCH);check(master!=null,"correcting lectern permits native assembly");s.getPlayerList().getPlayers().getFirst().teleportTo(10.5,-57,-2.5);return master.machineId();});c.waitTicks(4);aim(c,7.5,-58.9,.5);shot(c,"09-research-machine-assembled");aim(c,7.5,-58.5,-.5);shot(c,"10-research-lectern-facing-center");
            language(c,"zh_cn");w.getServer().runOnServer(s->s.getPlayerList().getPlayers().getFirst().teleportTo(7.5,-60,-2.5));c.waitTicks(4);open(c,R,true);success=w.getServer().computeOnServer(s->ResearchGameTests.find(s.overworld(),r->!r.scroll()));w.getServer().runOnServer(s->ResearchGameTests.fill((ResearchMenu)s.getPlayerList().getPlayers().getFirst().containerMenu,s.overworld(),success,2));c.waitFor(client->((ResearchMenu)client.player.containerMenu).preview()!=null);shot(c,"11-research-unknown-output");cursor(c,188,66,true);c.waitTicks(6);c.takeScreenshot("workstation-12-research-unknown-tooltip");click(c,188,66,true);c.waitFor(client->client.player.containerMenu.getCarried().is(Items.ENCHANTED_BOOK));w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();var m=(ResearchMenu)p.containerMenu;check(m.getSlot(0).getItem().isEmpty()&&m.getSlot(1).getItem().isEmpty()&&m.getSlot(2).getItem().getCount()==1&&ResearchWorldData.get(s).knows(p.getUUID(),success),"direct result commits existing recipe/discovery exactly once");});cursor(c,188,105,true);c.waitTicks(4);c.takeScreenshot("workstation-13-research-direct-result");click(c,114,198,true);w.getServer().runOnServer(s->ResearchGameTests.fill((ResearchMenu)s.getPlayerList().getPlayers().getFirst().containerMenu,s.overworld(),new ResearchPolicy.Recipe(success.b(),success.a()),2));c.waitFor(client->client.player.containerMenu.getSlot(3).getItem().is(Items.ENCHANTED_BOOK));shot(c,"14-research-known-preview");
            w.getServer().runOnServer(s->{var m=(ResearchMenu)s.getPlayerList().getPlayers().getFirst().containerMenu;var recipe=ResearchGameTests.find(s.overworld(),ResearchPolicy.Result::scroll);ResearchGameTests.fill(m,s.overworld(),recipe,2);m.getSlot(0).getItem().set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Preserved scroll input"));m.broadcastChanges();});c.waitTicks(5);var book=w.getServer().computeOnServer(s->((ResearchMenu)s.getPlayerList().getPlayers().getFirst().containerMenu).getSlot(0).getItem().copy());shift(c,188,66,true);w.getServer().runOnServer(s->{var m=(ResearchMenu)s.getPlayerList().getPlayers().getFirst().containerMenu;check(ItemStack.matches(book,m.getSlot(0).getItem())&&m.getSlot(2).getItem().getCount()==1&&m.getSlot(3).getItem().is(ResearchContent.LOST_SCROLL),"scroll branch preserves original book data and charges one core");});shot(c,"15-research-scroll-books-preserved");
            dId=w.getServer().computeOnServer(s->WorkstationStructure.controller(s.overworld(),D,WorkstationStructure.Kind.DISENCHANT).machineId());savedItems=counts(w);researchData=w.getServer().computeOnServer(s->ResearchWorldData.get(s).exportJson());report.append("Native survival sneak assembly of both specified patterns; preassembly GUI denied; outward lectern denied then inward correction accepted. Native mining restores four supported up mature clusters, zero shard drops, live particles cleared.\nFour sparse native FlyTowardsPositionParticles originate from all four corner indices, actual horizontal distance to core decreases, GUI suppresses motes.\nReal Shift disenchant consumes one book and six levels, only Sharpness removed and curse stays. Research direct output, unknown tooltip, known swapped preview and scroll data preservation all actual native menu packets.\n");
        }
        try(var w=save.open()) {
            c.waitTicks(6);check(savedItems.equals(counts(w)),"disconnect with open preview preserves exact inventory plus dropped inputs, never preview");w.getServer().runOnServer(s->{check(dId.equals(WorkstationStructure.controller(s.overworld(),D,WorkstationStructure.Kind.DISENCHANT).machineId())&&rId.equals(WorkstationStructure.controller(s.overworld(),R,WorkstationStructure.Kind.RESEARCH).machineId()),"both assembled identities survive actual disk reopen");check(com.google.gson.JsonParser.parseString(researchData).equals(com.google.gson.JsonParser.parseString(ResearchWorldData.get(s).exportJson())),"all research answers and discoveries unchanged after disk reopen");s.getPlayerList().getPlayers().getFirst().teleportTo(10.5,-57,-2.5);});c.waitTicks(4);aim(c,7.5,-58.9,.5);shot(c,"16-reloaded-research-machine");w.getServer().runOnServer(s->s.getPlayerList().getPlayers().getFirst().teleportTo(7.5,-60,-2.5));c.waitTicks(4);open(c,R,true);w.getServer().runOnServer(s->ResearchGameTests.fill((ResearchMenu)s.getPlayerList().getPlayers().getFirst().containerMenu,s.overworld(),success,2));c.waitTicks(4);var before=counts(w);w.getServer().runOnServer(s->s.overworld().destroyBlock(WorkstationStructure.position(R,10),false));c.waitForScreen(null);c.waitTicks(4);check(before.equals(counts(w)),"breaking research frame closes native menu and returns inputs once");aim(c,7.5,-58.9,.5);shot(c,"17-research-restored-and-inputs-returned");report.append("Actual world save/disconnect/reopen: both machine UUIDs, all research snapshot data and real item totals persisted. Breaking a research lectern with pending inputs auto-closes GUI and returns all materials once.\n");
        }
        try{var dir=Path.of("../reports/workstation-structures");Files.createDirectories(dir);Files.writeString(dir.resolve("client.txt"),report.toString());Files.writeString(dir.resolve("particles.csv"),telemetry.toString());}catch(Exception e){throw new RuntimeException(e);}
    }
}
